import{_ as d,a0 as s,w as a,s as n,ao as f,I as o,x as i,a1 as r,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"提高 LibreOffice 生产力的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"提高 LibreOffice 生产力的技巧 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"提高 LibreOffice 生产力的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"提高 LibreOffice 生产力的技巧 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20210922 My favorite LibreOffice productivity tips","title":"提高 LibreOffice 生产力的技巧","tag":"202302","desc":""},"relativePath":"202302/20210922 My favorite LibreOffice productivity tips.md","filePath":"[post].md"}'),u={name:"202302/20210922 My favorite LibreOffice productivity tips.md"};function p(b,e,O,m,c,L){const t=s("Link");return a(),n("div",null,[e[21]||(e[21]=f('<h1 id="提高-libreoffice-生产力的技巧" tabindex="-1">提高 LibreOffice 生产力的技巧 <a class="header-anchor" href="#提高-libreoffice-生产力的技巧" aria-label="Permalink to “提高 LibreOffice 生产力的技巧”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/11/161923gks1dsldq7dd1z67.jpg" alt=""></p><blockquote><p>今天我将和大家分享一些 LibreOffice 的键盘快捷键和排版技巧，希望能够帮你省下宝贵的时间。</p></blockquote><p>LibreOffice 是我首选的生产力应用程序。它是向教育工作者和学生推荐 Linux 发行版的最有力理由之一，无论是 PK-12 还是高等教育。新的学年快到了，我想也是时候推荐一些 LibreOffice 快捷方式和技巧，它们可以为你节省宝贵的时间。</p><h3 id="使用键盘快捷键让你工作更快捷" tabindex="-1">使用键盘快捷键让你工作更快捷 <a class="header-anchor" href="#使用键盘快捷键让你工作更快捷" aria-label="Permalink to “使用键盘快捷键让你工作更快捷”">​</a></h3><p>我平时经常使用键盘快捷键，以下是适用于所有 LibreOffice 应用程序的最常见的快捷键</p><ul><li><code>Ctrl+N</code> — 创建新文档</li><li><code>Ctrl+O</code> — 打开一个文档</li><li><code>Ctrl+S</code> — 保存文档</li><li><code>Ctrl+Shift+S</code> — 另存为</li><li><code>Ctrl+P</code> — 打印文档</li></ul><p>这些是仅适用于 LibreOffice Writer 的快捷键：</p><ul><li><code>Home</code> — 移动到当前行的初始位置</li><li><code>End</code> — 移动至当前行的结尾位置</li><li><code>Ctrl+Home</code> — 将光标移动到文档的初始位置</li><li><code>Ctrl+End</code> — 将光标移动到文档的结尾位置</li><li><code>Ctrl+A</code> — 全选</li><li><code>Ctrl+D</code> — 双下划线</li><li><code>Ctrl+E</code> — 居中</li><li><code>Ctrl+H</code> — 查找并替换</li><li><code>Ctrl+L</code> — 左对齐</li><li><code>Ctrl+R</code> — 右对齐</li></ul><p>功能键也大有用处：</p><ul><li><code>F2</code> — 打开公式栏</li><li><code>F3</code> — 自动补完</li><li><code>F5</code> — 打开导航器</li><li><code>F7</code> — 打开拼写和语法</li><li><code>F11</code> — 打开格式和排版</li><li><code>Shift+F11</code> — 创建新样式</li></ul><h3 id="文档格式" tabindex="-1">文档格式 <a class="header-anchor" href="#文档格式" aria-label="Permalink to “文档格式”">​</a></h3><p>文档格式有很多种，LibreOffice 支持其中很多文档格式。默认情况下，LibreOffice 将文档保存为 <ruby>开放文档格式<rt>Open Document Format</rt></ruby>（ODF），这是一种开源标准，将样式表和数据存储在 ZIP 容器中，文本文档标记为 ODT，电子表格标记为 ODS，演示文稿标记为 ODP。它是一种灵活的格式，由 LibreOffice 社区和文档基金会维护。</p><p>ODF 是默认启用的，因此你无需执行任何操作即可让 LibreOffice 使用这种格式。</p>',14)),o("p",null,[e[1]||(e[1]=i("另一种文档开放规范是微软的 ",-1)),r(t,{href:"https://www.iso.org/standard/71691.html"},{default:l(()=>[...e[0]||(e[0]=[i("Office Open XML（OOXML）格式",-1)])]),_:1}),e[2]||(e[2]=i("。它是一个 ISO 标准，并得到所有主要办公解决方案的良好支持。",-1))]),e[22]||(e[22]=f('<p>如果你与使用微软 Office 的人一起工作（它本身不是开源的，但它确实使用开放的 OOXML 格式），那么他们肯定习惯于 DOCX、XLSX 和 PPTX 格式，并且可能无法打开 ODT、ODS 或 ODP 文件。你可以通过在 LibreOffice 中将 OOXML 设置为默认格式来避免很多混乱。</p><p>将 OOXML 设置为你的首选格式：</p><ol><li>单击 “<ruby>工具<rt>Tools</rt></ruby>” 菜单并选择菜单底部的 “<ruby>选项<rt>Options</rt></ruby>”。</li><li>在 “<ruby>选项<rt>Options</rt></ruby>” 窗口中，单击左侧面板中的 “<ruby>加载/保存<rt>Load/Save</rt></ruby>” 类别，然后选择 “<ruby>常规<rt>General</rt></ruby>”。<br><img src="https://opensource.com/sites/default/files/uploads/libreoffice-panel.jpg" alt="LibreOffice设置面板" title="LibreOffice settings panel"></li><li>导航到 “<ruby>默认文件格式和 ODF 设置<rt>Default File Format and ODF Settings</rt></ruby>” 部分。</li><li>在 “<ruby>文档类型<rt>Document type</rt></ruby>” 选择 “<ruby>文本文档<rt>Text document</rt></ruby>”，并在 “<ruby>始终另存为<rt>Always save as</rt></ruby>” 下拉列表选择 “Open XML (Transitional) (*.docx) ”。</li><li>点击 “<ruby>应用<rt>Apply</rt></ruby>” 然后点击 “<ruby>确定<rt>OK</rt></ruby>”。</li><li>取消选择 “<ruby>未以 ODF 或默认格式保存时发出警告<rt>Warn when not saving in ODF or default format </rt></ruby>” 以避免在保存时出现确认对话框。 <img src="https://opensource.com/sites/default/files/uploads/libreoffice-save-format.jpg" alt="LibreOffice 保存格式" title="LibreOffice save formats"></li></ol><p>按照相同的逻辑重复，重复相同的过程用于 XLSX 和 PPTX 文档。</p><h3 id="让办公更自由" tabindex="-1">让办公更自由 <a class="header-anchor" href="#让办公更自由" aria-label="Permalink to “让办公更自由”">​</a></h3>',5)),o("p",null,[e[4]||(e[4]=i("LibreOffice 项目由蓬勃发展的用户和开发人员社区与文档基金会共同管理。这包括工程指导委员会、董事会、独立开发人员、设计师和翻译人员等。这些团队始终欢迎各位的贡献，因此如果你渴望参与一个超赞的开源项目，请不要犹豫 ",-1)),r(t,{href:"https://www.libreoffice.org/community/get-involved/"},{default:l(()=>[...e[3]||(e[3]=[i("参与进来",-1)])]),_:1}),e[5]||(e[5]=i("。",-1))]),e[23]||(e[23]=o("hr",null,null,-1)),o("p",null,[e[7]||(e[7]=i("via: ",-1)),r(t,{href:"https://opensource.com/article/21/9/libreoffice-tips"},{default:l(()=>[...e[6]||(e[6]=[i("https://opensource.com/article/21/9/libreoffice-tips",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=i("作者：",-1)),r(t,{href:"https://opensource.com/users/don-watkins"},{default:l(()=>[...e[8]||(e[8]=[i("Don Watkins",-1)])]),_:1}),e[13]||(e[13]=i(" 选题：",-1)),r(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[9]||(e[9]=[i("lujun9972",-1)])]),_:1}),e[14]||(e[14]=i(" 译者：",-1)),r(t,{href:"https://github.com/XiaotingHuang22"},{default:l(()=>[...e[10]||(e[10]=[i("XiaotingHuang22",-1)])]),_:1}),e[15]||(e[15]=i(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[11]||(e[11]=[i("wxy",-1)])]),_:1})]),o("p",null,[e[18]||(e[18]=i("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[16]||(e[16]=[i("LCTT",-1)])]),_:1}),e[19]||(e[19]=i(" 原创编译，",-1)),r(t,{href:"https://linux.cn/"},{default:l(()=>[...e[17]||(e[17]=[i("Linux中国",-1)])]),_:1}),e[20]||(e[20]=i(" 荣誉推出",-1))])])}const g=d(u,[["render",p]]);export{C as __pageData,g as default};
